function parsePDFRange(value,count){if(!Number.isInteger(count)||count<1)throw Error('Add pages first.');if(!String(value).trim()||String(value).trim().toLowerCase()==='all')return Array.from({length:count},(_,i)=>i);const out=[];for(const entry of String(value).split(',')){const match=entry.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!match)throw Error('Use page numbers such as 1-3, 5, 8.');let a=+match[1],b=+(match[2]||match[1]);if(a<1||b<1||a>count||b>count||b<a)throw Error('Page range must be between 1 and '+count+'.');for(let i=a;i<=b;i++)if(!out.includes(i-1))out.push(i-1);}return out;}
